// ============================================================
// LIỆT KÊ TOÀN BỘ "THỰC ĐƠN" CHỈ SỐ của endpoint ratios (mã VNM)
// -> tìm itemCode/ratioCode của ROE, ROA, Nợ/Vốn, Biên LN.
// ============================================================
const headers = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
  'Accept': 'application/json, text/plain, */*',
  'Referer': 'https://dstock.vndirect.com.vn/',
};

const tryFetch = async (url) => {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers, json: false, timeout: 20000 });
    let p; try { p = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { return { err: 'parse' }; }
    return { data: (p && p.data) || [] };
  } catch (e) {
    return { err: (e.message || String(e)) };
  }
};

// Thử nhiều biến thể để lấy được càng nhiều itemCode càng tốt
const variants = [
  'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:VNM&sort=reportDate:desc&size=500',
  'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:VNM~reportType:QUARTER&sort=reportDate:desc&size=300',
  'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:VNM~reportType:ANNUAL&sort=reportDate:desc&size=300',
];

const seen = new Map();
const log = [];
for (const url of variants) {
  const r = await tryFetch(url);
  if (r.err) { log.push('❌ ' + url.split('?')[1] + ' -> ' + r.err); continue; }
  log.push('✅ ' + url.split('?')[1] + ' -> ' + r.data.length + ' dòng');
  for (const d of r.data) {
    const key = d.itemCode + '|' + d.ratioCode;
    if (!seen.has(key)) seen.set(key, {
      itemCode: d.itemCode,
      ratioCode: d.ratioCode,
      itemName: (d.itemName || '').trim(),
      reportDate: d.reportDate,
      value: d.value,
    });
  }
}

const list = [...seen.values()].sort((a, b) => String(a.itemCode).localeCompare(String(b.itemCode)));
return [
  { json: { TONG_KET: 'Tìm thấy ' + list.length + ' chỉ số khác nhau', log } },
  ...list.map(x => ({ json: x })),
];
